<js>
var _hc = `
var ORIGIN = "https://6637.h55e.com";
var API = ORIGIN + "/douyin/douyin622web.ashx";
var CRYPTO_B64 = "";
var HAPPY_B64 = "";
var LV_B64 = "";

function loadLib(b64){
  try {
    var s = document.createElement('script');
    s.textContent = atob(b64);
    document.head.appendChild(s);
    return true;
  } catch(e) { return false; }
}
loadLib(CRYPTO_B64);
loadLib(HAPPY_B64);
loadLib(LV_B64);

var cur = 0, total = 0, page = 1, pagecount = 999, slides = [], loading = false;
var vp = document.getElementById('vp');
var stack = document.getElementById('stack');
var metaBox = document.getElementById('meta');
var bar = document.getElementById('bar');

function clearVideos(){ slides.forEach(function(s){ if(s.vid){ try{ if(s.vid._hls){ s.vid._hls.destroy(); } }catch(e){} s.vid.pause(); try{s.vid.removeAttribute('src'); s.vid.load();}catch(e){} } }); stack.innerHTML=''; slides=[]; cur=0; total=0; }

function buildSlides(list){
  list.forEach(function(v){
    var url = (v.xl1||"") + (v.vurl||"");
    var cover = (v.firsturl||"") + (v.coverimg||"");
    var slide = document.createElement('div'); slide.className='slide';
    if(cover){ var ph=document.createElement('div'); ph.className='ph'; var img=document.createElement('img'); img.src=cover; img.onerror=function(){ph.style.display='none';}; ph.appendChild(img); slide.appendChild(ph); }
    var vid=document.createElement('video'); vid.className='vd'; vid.loop=true; vid.preload='metadata'; vid.poster=cover; vid.muted=true; vid.setAttribute('playsinline',''); vid.setAttribute('webkit-playsinline',''); vid.setAttribute('x5-playsinline',''); vid.setAttribute('x5-video-player-type','h5'); slide.appendChild(vid);
    var meta=document.createElement('div'); meta.className='meta'; var h3=document.createElement('h3'); h3.textContent=(v.title||''); meta.appendChild(h3); slide.appendChild(meta);
    stack.appendChild(slide);
    slides.push({el:slide, vid:vid, url:url, loaded:false});
  });
  total = slides.length;
  go(0);
}

function loadAndPlay(i){
  var it = slides[i]; if(!it) return;
  if(!it.loaded && it.url){
    if(window.Hls && Hls.isSupported()){
      var hls=new Hls({maxBufferLength:30}); hls.loadSource(it.url); hls.attachMedia(it.vid);
      hls.on(Hls.Events.MANIFEST_PARSED, function(){ it.vid.play().catch(function(){}); });
      hls.on(Hls.Events.ERROR, function(e,d){ if(d && d.fatal){ try{hls.destroy();}catch(x){} } });
      it.vid._hls=hls;
    } else if(it.vid.canPlayType && it.vid.canPlayType('application/vnd.apple.mpegurl')){
      it.vid.src=it.url; it.vid.play().catch(function(){});
    }
    it.loaded=true;
  } else if(it.vid && it.vid._hls){
    it.vid.play().catch(function(){});
  }
}

function go(i){
  if(i<0) i=0; if(i>=total) i=total-1;
  for(var k=0;k<slides.length;k++){ if(k!==i && slides[k].vid){ slides[k].vid.pause(); } }
  cur=i;
  stack.style.transition='transform .38s cubic-bezier(.22,.61,.36,1)';
  stack.style.transform='translateY(' + (-i*100) + 'vh)';
  loadAndPlay(i);
  if(slides[i] && slides[i].el.querySelector('h3')) metaBox.textContent = slides[i].el.querySelector('h3').textContent;
  if(i>=total-3 && page<pagecount && !loading){ loadPage(page+1); }
}

function postData(action, extra){
  return new Promise(function(resolve,reject){
    if(typeof mkparms !== 'function'){ reject(new Error('no mkparms')); return; }
    var p = mkparms(Object.assign({action:action, pageindex:page, pagesize:20}, extra||{}));
    var body = Object.keys(p).map(function(k){ return encodeURIComponent(k)+'='+encodeURIComponent(p[k]); }).join('&');
    var xhr = new XMLHttpRequest();
    xhr.open('POST', API, true);
    xhr.setRequestHeader('Content-Type','application/x-www-form-urlencoded; charset=UTF-8');
    xhr.setRequestHeader('X-Requested-With','XMLHttpRequest');
    xhr.onload=function(){ try{ resolve(JSON.parse(xhr.responseText)); }catch(e){ reject(e); } };
    xhr.onerror=function(){ reject(new Error('net')); };
    xhr.send(body);
  });
}

function loadPage(pg, extra){
  loading=true; page=pg;
  postData('gettiktokvideosh5', extra).then(function(res){
    loading=false;
    if(res && res.status==1){ if(res.pagecount) pagecount=res.pagecount; if(res.data && res.data.length) buildSlides(res.data); }
  }).catch(function(){ loading=false; bar.textContent='加载失败，点屏幕重试'; });
}

var sy=0, dragging=false;
vp.addEventListener('touchstart', function(e){ sy=e.touches[0].clientY; dragging=true; if(slides[cur]&&slides[cur].vid){ slides[cur].vid.muted=false; } }, {passive:true});
vp.addEventListener('touchmove', function(e){ if(!dragging) return; var dy=e.touches[0].clientY-sy; stack.style.transition='none'; stack.style.transform='translateY('+((-cur*100)+ dy/window.innerHeight*100)+'vh)'; }, {passive:true});
vp.addEventListener('touchend', function(e){ if(!dragging) return; dragging=false; var dy=e.changedTouches[0].clientY-sy; if(dy<-50) go(cur+1); else if(dy>50) go(cur-1); else go(cur); });

var my=0, mdrag=false;
vp.addEventListener('mousedown', function(e){ my=e.clientY; mdrag=true; if(slides[cur]&&slides[cur].vid) slides[cur].vid.muted=false; });
vp.addEventListener('mousemove', function(e){ if(!mdrag) return; var dy=e.clientY-my; stack.style.transition='none'; stack.style.transform='translateY('+((-cur*100)+ dy/window.innerHeight*100)+'vh)'; });
vp.addEventListener('mouseup', function(e){ if(!mdrag) return; mdrag=false; var dy=e.clientY-my; if(dy<-50) go(cur+1); else if(dy>50) go(cur-1); else go(cur); });

var box=document.getElementById('search');
var sinput=document.getElementById('sinput');
function toggleSearch(){ box.style.display = (box.style.display==='none'||!box.style.display)?'block':'none'; }
function doSearch(){
  var q=sinput.value.trim(); if(!q) return;
  clearVideos(); page=1; loading=true; bar.textContent='搜索中…';
  postData('douyinsearchres', {search:q, skey:''}).then(function(res){
    loading=false;
    if(res && res.status==1){ if(res.pagecount) pagecount=res.pagecount; if(res.data&&res.data.length) buildSlides(res.data); else bar.textContent='无结果'; }
  }).catch(function(){ loading=false; bar.textContent='搜索失败'; });
}
window.__toggleSearch=toggleSearch; window.__doSearch=doSearch;

bar.textContent='加载中…';
(function loadHls(cb){
  if(window.Hls) return cb();
  var s=document.createElement('script'); s.src='https://cdn.jsdelivr.net/npm/hls.js@1.5.13/dist/hls.min.js';
  s.onload=cb; s.onerror=function(){ var s2=document.createElement('script'); s2.src='https://zhkshk323.ddzd123.com/web/dplayer/hls.min_v1.js'; s2.onload=cb; s2.onerror=function(){ bar.textContent='播放库加载失败'; }; document.head.appendChild(s2); };
  document.head.appendChild(s);
})(function(){ loadPage(1); });
`;
result = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover"><title>抖音菜单·上下滑</title><style>html,body{margin:0;padding:0;height:100%;background:#000;overflow:hidden;font-family:-apple-system,Roboto,sans-serif}#vp{position:fixed;left:0;top:0;right:0;bottom:0;overflow:hidden;touch-action:none}#stack{will-change:transform}.slide{position:relative;height:100vh;width:100vw;overflow:hidden;background:#0a0a0a}.slide .ph{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:#0a0a0a}.slide .ph img{max-width:100%;max-height:100%;object-fit:contain}.slide video.vd{position:absolute;left:0;top:0;width:100%;height:100%;object-fit:contain;background:#000}.slide .meta{position:absolute;left:0;right:0;bottom:64px;padding:40px 14px 14px;background:linear-gradient(transparent,rgba(0,0,0,.85));z-index:3;pointer-events:none;text-shadow:0 1px 3px rgba(0,0,0,.8)}.slide .meta h3{margin:0;font-size:15px;line-height:1.45;color:#fff;font-weight:500}#meta{position:fixed;left:12px;right:64px;bottom:18px;z-index:11;color:#fff;font-size:14px;text-shadow:0 1px 3px #000}#bar{position:fixed;left:0;right:0;top:0;z-index:12;color:#fff;font-size:12px;text-align:center;padding:6px;background:rgba(0,0,0,.4)}#search{display:none;position:fixed;left:0;right:0;top:0;z-index:13;padding:8px;background:rgba(0,0,0,.85)}#sinput{width:70%;padding:8px;border:0;border-radius:6px}#search button{padding:8px 12px;border:0;border-radius:6px;background:#e0407a;color:#fff}</style></head><body><div id="bar"></div><div id="vp"><div id="stack"></div></div><div id="meta"></div><div id="search"><input id="sinput" placeholder="搜索视频"><button onclick="__doSearch()">搜</button> <button onclick="__toggleSearch()">关</button></div><div style="position:fixed;right:10px;top:40px;z-index:13"><button onclick="__toggleSearch()" style="padding:6px 10px;border:0;border-radius:6px;background:rgba(255,255,255,.2);color:#fff">搜</button></div><script>${_hc}</script></body></html>`;

